export function lifeStage(s){const months=(Number(s.month.slice(0,4))*12+Number(s.month.slice(5)))-(Number(s.start.slice(0,4))*12+Number(s.start.slice(5)));const years=s.startAge+Math.floor(months/12);if(years<3)return {years,key:'baby',label:'영유아',action:'모빌을 바라보는 하루'};if(years<7)return {years,key:'child',label:'유아',action:'세발자전거로 넓어지는 세계'};if(years<13)return {years,key:'school',label:'어린이',action:'배우고 자라는 시간'};if(years<19)return {years,key:'teen',label:'청소년',action:'나의 내일을 준비하는 시간'};if(years<40)return {years,key:'young',label:'청년',action:s.business?'가게의 하루를 열다':s.job?'일하며 나의 생활을 만들다':'나의 시간을 즐기다'};if(years<60)return {years,key:'adult',label:'중년',action:s.business?'나의 가게를 돌보다':s.job?'일과 생활 사이의 균형':'책과 함께 쉬어가는 하루'};if(years<70)return {years,key:'mature',label:'장년',action:'산책으로 하루를 시작하다'};return {years,key:'senior',label:'노년',action:'식물을 돌보며 보내는 시간'};}
const head=(x,y,r=17)=>`<circle cx="${x}" cy="${y}" r="${r}" fill="#263b54"/>`;
const stroke=(d,color='#263b54',width=10)=>`<path d="${d}" fill="none" stroke="${color}" stroke-width="${width}" stroke-linecap="round" stroke-linejoin="round"/>`;
export function avatarScene(s){const a=lifeStage(s);let scene='';
 if(a.key==='baby')scene=`<path d="M65 215V150M235 215V150M65 184H235" stroke="#96badd" stroke-width="9" fill="none"/><rect x="72" y="160" width="157" height="25" rx="12" fill="#d1e6fa"/>${head(106,144,16)}<g class="avatar-limb">${stroke('M124 150L167 150','#218aff',22)}${stroke('M153 148L165 127','#218aff',9)}${stroke('M166 151L189 135','#218aff',9)}</g><path d="M218 145V57H167" stroke="#96badd" stroke-width="6" fill="none"/><g class="avatar-mobile"><path d="M174 60V82M195 60V94" stroke="#96badd" stroke-width="2"/><circle cx="174" cy="90" r="9" fill="#efc765"/><path d="M195 94l10 8-4 12h-12l-4-12Z" fill="#218aff"/></g>`;
 else if(a.key==='child')scene=`<circle cx="104" cy="196" r="27" fill="white" stroke="#96badd" stroke-width="7"/><circle cx="211" cy="200" r="19" fill="white" stroke="#96badd" stroke-width="7"/>${stroke('M104 196L151 169L199 197M151 169L147 149M182 168L202 168L211 197','#218aff',7)}${head(140,92,18)}<path d="M126 117L150 117L160 149L132 157Z" fill="#218aff"/>${stroke('M148 126L178 146')}<g class="avatar-pedal">${stroke('M140 151L161 173L142 187')}<circle cx="148" cy="180" r="5" fill="#efc765"/></g>`;
 else if(a.key==='school'||a.key==='teen')scene=`<rect x="100" y="155" width="124" height="9" rx="4" fill="#96badd"/><path d="M111 165V216M216 165V216" stroke="#96badd" stroke-width="6"/>${head(120,84,a.key==='school'?19:17)}<path d="M108 108h26l9 45h-41Z" fill="${a.key==='school'?'#218aff':'#42658a'}"/>${stroke('M115 156L114 183L133 211')}${stroke('M133 156L148 183L162 211')}<g class="avatar-read">${stroke('M131 124L158 147', '#263b54',8)}<path d="M146 151l28-9 28 9v8h-56Z" fill="#efc765"/></g><rect x="90" y="118" width="12" height="33" rx="4" fill="#bdd8f4"/>`;
 else if(a.key==='senior')scene=`${head(138,70)}<path d="M121 94h33l9 61h-49Z" fill="#779bb4"/>${stroke('M128 157L125 209')}${stroke('M149 157L157 209')}<g class="avatar-water">${stroke('M154 111L183 133')}<path d="M178 133h21v18h-21Z" fill="#218aff"/><path d="M198 140l20 13" stroke="#218aff" stroke-width="5"/></g><path d="M214 178h32l-5 33h-22Z" fill="#efc765"/>${stroke('M229 177V144','#609b7a',4)}<ellipse cx="220" cy="150" rx="10" ry="5" fill="#609b7a"/><ellipse cx="239" cy="159" rx="10" ry="5" fill="#609b7a"/>`;
 else if(a.key==='mature')scene=`${head(143,64)}<path d="M130 89h28l3 62h-38Z" fill="#218aff"/><g class="avatar-walk">${stroke('M134 153L119 207')}${stroke('M150 153L172 207')}${stroke('M130 105L111 137')}${stroke('M156 105L177 129')}</g><path d="M60 205h31M218 205h28" stroke="#a4c7ad" stroke-width="5" stroke-linecap="round"/>`;
 else if(s.business)scene=`<rect x="65" y="160" width="174" height="56" rx="5" fill="#d6e8f7"/><path d="M63 157h178" stroke="#96badd" stroke-width="8"/>${head(143,78)}<path d="M127 101h32l4 51h-41Z" fill="#42658a"/><path d="M131 113h24v40h-24Z" fill="#218aff"/><g class="avatar-read">${stroke('M155 118L185 140','#263b54',8)}<rect x="184" y="138" width="23" height="17" rx="3" fill="#efc765"/></g>`;
 else if(s.job)scene=`${head(140,65)}<path d="M124 89h33l8 63h-48Z" fill="#42658a"/><path d="M140 94l-5 20 6 18 6-18Z" fill="#9acbfa"/>${stroke('M129 153L123 212')}${stroke('M151 153L163 212')}<g class="avatar-work">${stroke('M156 107L179 149')}<rect x="169" y="148" width="34" height="25" rx="4" fill="#218aff"/></g>${stroke('M123 108L105 143')}`;
 else scene=`${head(133,78)}<path d="M119 102h30l7 56h-45Z" fill="#218aff"/>${stroke('M123 159L110 210')}${stroke('M146 159L166 210')}<g class="avatar-read">${stroke('M144 123L169 142','#263b54',8)}<path d="M155 139l21-6 23 6v24l-23-6-21 6Z" fill="#efc765"/></g>`;
 return `<div class="avatar-stage avatar-${a.key}"><svg viewBox="0 0 300 260" role="img" aria-label="${a.years}세 ${a.label}, ${a.action}. 얼굴 없는 픽토그램"><ellipse cx="150" cy="226" rx="100" ry="9" fill="#ddebf6"/>${scene}</svg><span class="avatar-age">${a.years}<small>세</small></span><span class="avatar-label">${a.label}</span><p>${a.action}</p></div>`;
}
